<?php
require __DIR__.'/c2a_runtime.php';
$c2Resources=[];
function vReturnFixture(string $label,string $mode,array $outcomes):array {
    global $pdo;$qty=array_sum($outcomes);$stock=$mode==='Serialized'?$qty+1:5;$resource=cResource($label,$mode,$stock);$id=cRequest([[$resource,$qty]]);cApprove($id);cRelease($id);
    $line=cRows('SELECT * FROM request_items WHERE request_id=?',[$id])[0];$p=['condition_notes'=>'Synthetic C2A outcomes'];
    if($mode==='Serialized'){$conditions=[];foreach($outcomes as $condition=>$count)for($n=0;$n<$count;$n++)$conditions[]=$condition;$units=cRows('SELECT unit_id FROM request_item_units WHERE request_item_id=? ORDER BY allocation_id',[$line['request_item_id']]);foreach($units as $i=>$unit)$p['lines'][$line['request_item_id']]['units'][$unit['unit_id']]=['condition'=>$conditions[$i]];
    }else{$p['lines'][$line['request_item_id']]['outcomes']=$outcomes;}
    cHttp('borrower_a','borrower/return_submit.php?request_id='.$id,$p);cAssert(cRows('SELECT status FROM resource_requests WHERE request_id=?',[$id])[0]['status']==='Return','Normal outcome submission failed');
    $inspection=['action'=>'approve','inspection_remarks'=>'Synthetic C2A exact outcomes'];foreach(cRows('SELECT d.* FROM return_submission_items d JOIN return_submissions s ON s.return_id=d.return_id WHERE s.request_id=? ORDER BY return_item_id',[$id]) as $d)$inspection['inspection'][$d['return_item_id']]=['condition'=>$d['reported_condition'],'remarks'=>'Synthetic C2A'];
    return ['request'=>$id,'resource'=>$resource,'stock'=>$stock,'quantity'=>$qty,'mode'=>$mode,'outcomes'=>$outcomes,'inspection'=>$inspection];
}
function vOutcomeCheck(array $fixture,array $before,array $after):array {
    $a=$after['tables'];$state=$a['requests'][0];$resource=$a['resources'][0];$lost=$fixture['outcomes']['Lost']??0;$damaged=$fixture['outcomes']['Damaged']??0;$good=$fixture['outcomes']['Good']??0;
    cAssert($state['status']==='Returned'&&$state['return_date']!==null,'Return did not settle once');
    cAssert((int)$resource['total_stock']===$fixture['stock']-$lost&&(int)$resource['available_stock']===$fixture['stock']-$fixture['quantity']+$good&&(int)$resource['under_repair_stock']===$damaged,'Damaged/Lost/Good stock arithmetic failed');
    cAssert((int)$a['items'][0]['returned_quantity']===$fixture['quantity'],'Return quantity applied incorrectly');
    cAssert(count($a['liabilities'])===0&&count($a['maintenance'])===0,'Inspection bypassed explicit accountability/GSO Head work-order decision');
    cAssert(cEvents($fixture['request'],'return_accepted')===1,'Acceptance event duplicated');cAssert(count(array_diff_key($after['outbox_hashes'],$before['outbox_hashes']))===1,'Acceptance capture duplicated');
    if($fixture['mode']==='Serialized'){$counts=array_count_values(array_column($a['units'],'status'));cAssert(($counts['Lost']??0)===$lost&&($counts['Under Repair']??0)===$damaged&&($counts['Available']??0)===$fixture['stock']-$fixture['quantity']+$good,'Serialized return affected wrong units');foreach($a['allocations'] as $allocation)cAssert($allocation['returned_at']!==null,'Returned unit allocation left open');}
    return ['status'=>'Returned','total'=>(int)$resource['total_stock'],'available'=>(int)$resource['available_stock'],'under_repair'=>(int)$resource['under_repair_stock'],'outcomes'=>$fixture['outcomes'],'work_orders'=>0,'liabilities'=>0,'accepted_events'=>1];
}
function vProposal(int $id,int $day):array {return ['action'=>'create','date_needed'=>date('Y-m-d',strtotime('+'.$day.' days')),'facility_slot'=>'AM','start_time'=>'09:00','end_time'=>'10:00','reason'=>'Synthetic C2A client proposal'];}
function vPropose(int $id,int $day):int {cHttp('borrower_a','borrower/reschedule.php?request_id='.$id,vProposal($id,$day));$p=cRows("SELECT reschedule_id FROM request_reschedule_history WHERE request_id=? AND status='Pending'",[$id]);cAssert(count($p)===1,'Normal reschedule proposal failed');return (int)$p[0]['reschedule_id'];}
function vPlan(string $label,string $mode='Aggregate'):array {
    global $m;$stock=$mode==='Serialized'?2:5;$r=cResource($label,$mode,$stock);$data=['action'=>'create_plan','resource_id'=>$r,'quantity'=>$mode==='Serialized'?1:2,'equipment_unit_id'=>$mode==='Serialized'?cRows('SELECT unit_id FROM equipment_units WHERE resource_id=? ORDER BY unit_id',[$r])[0]['unit_id']:0,'title'=>'Synthetic C2A '.$label,'recurrence'=>'Once','next_due_date'=>date('Y-m-d'),'duration_days'=>1,'assigned_to'=>$m['users'][13]['user_id']];
    cHttp('gso_a','admin/preventive_plans.php',$data);$plans=cRows('SELECT * FROM preventive_maintenance_plans WHERE resource_id=?',[$r]);cAssert(count($plans)===1,'Normal preventive plan creation failed');return ['resource'=>$r,'plan'=>(int)$plans[0]['plan_id'],'stock'=>$stock,'hold'=>(int)$data['quantity'],'mode'=>$mode];
}
function vGenerate(array $plan):int {cHttp('gso_a','admin/preventive_plans.php',['action'=>'generate','plan_id'=>$plan['plan']]);$rows=cRows('SELECT maintenance_id,status FROM maintenance_schedules WHERE preventive_plan_id=?',[$plan['plan']]);cAssert(count($rows)===1&&$rows[0]['status']==='Scheduled','Normal generation failed or auto-started');return (int)$rows[0]['maintenance_id'];}
function vWorkFromReturn(array $fixture):int {
    global $m;$id=$fixture['request'];cHttp('gso_a','admin/review_return.php?request_id='.$id,$fixture['inspection']);cAssert(cRows('SELECT status FROM resource_requests WHERE request_id=?',[$id])[0]['status']==='Returned','Normal Damaged inspection failed');
    $detail=cRows('SELECT d.return_item_id FROM return_submission_items d JOIN return_submissions s ON s.return_id=d.return_id WHERE s.request_id=?',[$id])[0]['return_item_id'];$p=['action'=>'create_return_work_order','return_item_id'=>$detail,'assigned_to'=>$m['users'][13]['user_id'],'duration_days'=>1,'remarks'=>'Synthetic C2A Head-confirmed work'];
    cHttp('gso_b','admin/maintenance.php',$p);cAssert(count(cRows('SELECT * FROM maintenance_schedules WHERE source_return_item_id=?',[$detail]))===0,'GSO Staff bypassed GSO Head confirmation');
    cHttp('gso_a','admin/maintenance.php',$p);$work=cRows('SELECT * FROM maintenance_schedules WHERE source_return_item_id=?',[$detail]);cAssert(count($work)===1&&$work[0]['status']==='In Progress'&&$work[0]['completed_at']===null,'Head-confirmed corrective work creation failed');return (int)$work[0]['maintenance_id'];
}
try{
    cLogin('gso_a',$m['users'][12]);cLogin('gso_b',$m['users'][13]);cLogin('gso_head_b',$m['users'][12]);cLogin('borrower_a',$m['users'][0]);cLogin('borrower_b',$m['users'][0]);cAudit('before');cLogs('before');
    $specs=['damaged_aggregate'=>5,'damaged_serialized'=>5,'lost_aggregate'=>5,'lost_serialized'=>5,'mixed_aggregate'=>3,'mixed_serialized'=>3,'proposal'=>5,'reschedule_collision'=>5,'reschedule_decision'=>5,'maintenance_start'=>5,'complete_aggregate'=>5,'complete_serialized'=>5,'maintenance_conflict'=>5,'preventive_generate'=>3];
    foreach($specs as $group=>$iterations)for($i=1;$i<=$iterations;$i++){
        $label=$group.'_'.str_pad((string)$i,2,'0',STR_PAD_LEFT);$c2Resources=[];
        if(in_array($label,array_column($results,'label'),true)){echo 'PRESERVED PASS '.$label.PHP_EOL;continue;}
        if(str_starts_with($group,'damaged_')||str_starts_with($group,'lost_')||str_starts_with($group,'mixed_')){
            $mode=str_ends_with($group,'serialized')?'Serialized':'Aggregate';$outcomes=str_starts_with($group,'mixed_')?['Good'=>1,'Damaged'=>1,'Lost'=>1]:[(str_starts_with($group,'lost_')?'Lost':'Damaged')=>($mode==='Serialized'?1:2)];$fixture=vReturnFixture($label,$mode,$outcomes);$ids=[$fixture['request']];$c2Resources=[$fixture['resource']];$path='admin/review_return.php?request_id='.$ids[0];$calls=[['gso_a',$path,$fixture['inspection']],['gso_b',$path,$fixture['inspection']]];$verify=fn($b,$a)=>vOutcomeCheck($fixture,$b,$a);
        }elseif(in_array($group,['proposal','reschedule_collision','reschedule_decision'],true)){
            $r=cResource($label,'Facility',1);$a=cRequest([[$r,1]],7);cApprove($a);$ids=[$a];$c2Resources=[$r];
            if($group==='proposal'){$calls=[['borrower_a','borrower/reschedule.php?request_id='.$a,vProposal($a,14)],['borrower_b','borrower/reschedule.php?request_id='.$a,vProposal($a,15)]];
                $verify=function($before,$after)use($a){$tables=$after['tables'];cAssert($before['tables']['requests']===$tables['requests']&&$before['tables']['items']===$tables['items'],'Proposal changed authoritative booking');cAssert(count($tables['reschedules'])===1&&$tables['reschedules'][0]['status']==='Pending','Duplicate authoritative pending proposal');cAssert(cEvents($a,'reschedule_submitted')===1,'Duplicate proposal event');return ['pending_proposals'=>1,'authoritative_schedule'=>'unchanged','proposed_time_reserved'=>false];};
            }elseif($group==='reschedule_collision'){$b=cRequest([[$r,1]],8);cApprove($b);$ids[]=$b;$pa=vPropose($a,14);$pb=vPropose($b,14);$calls=[['gso_a','admin/reschedules.php',['request_id'=>$a,'reschedule_id'=>$pa,'action'=>'approve','review_remarks'=>'Synthetic C2A']],['gso_b','admin/reschedules.php',['request_id'=>$b,'reschedule_id'=>$pb,'action'=>'approve','review_remarks'=>'Synthetic C2A']]];
                $verify=function($before,$after){$history=$after['tables']['reschedules'];cAssert(count(array_filter($history,fn($h)=>$h['status']==='Approved'))===1&&count(array_filter($history,fn($h)=>$h['status']==='Pending'))===1,'Reschedule collision decision state invalid');foreach($history as $h){$r=array_values(array_filter($after['tables']['requests'],fn($r)=>$r['request_id']===$h['request_id']))[0];cAssert($r['date_needed']===($h['status']==='Approved'?$h['new_date_needed']:$h['old_date_needed']),'Losing original schedule not preserved');}return ['approved_proposals'=>1,'loser'=>'Pending, original retained','confirmed_conflicts'=>0];};
            }else{$p=vPropose($a,14);$calls=[['gso_a','admin/reschedules.php',['request_id'=>$a,'reschedule_id'=>$p,'action'=>'approve','review_remarks'=>'Synthetic C2A approve']],['gso_b','admin/reschedules.php',['request_id'=>$a,'reschedule_id'=>$p,'action'=>'reject','review_remarks'=>'Synthetic C2A reject']]];
                $verify=function($before,$after)use($a){$h=$after['tables']['reschedules'][0];$r=$after['tables']['requests'][0];cAssert(in_array($h['status'],['Approved','Rejected'],true)&&$h['reviewed_by']!==null&&$h['processed_at']!==null,'Decision not terminal');cAssert($r['date_needed']===($h['status']==='Approved'?$h['new_date_needed']:$h['old_date_needed']),'Contradictory authoritative schedule');cAssert(cEvents($a,'reschedule_approved')+cEvents($a,'reschedule_rejected')===1,'Two terminal decision events');return ['decision'=>$h['status'],'authoritative_date'=>$r['date_needed'],'terminal_events'=>1];};}
        }elseif(str_starts_with($group,'complete_')){
            $mode=$group==='complete_serialized'?'Serialized':'Aggregate';$fixture=vReturnFixture($label,$mode,['Damaged'=>$mode==='Serialized'?1:2]);$job=vWorkFromReturn($fixture);$ids=[$fixture['request']];$c2Resources=[$fixture['resource']];$payload=['action'=>'complete_schedule','maintenance_id'=>$job,'completion_notes'=>'Synthetic C2A explicit completion'];$calls=[['gso_a','admin/maintenance.php',$payload],['gso_b','admin/maintenance.php',$payload]];
            $verify=function($before,$after)use($fixture){$job=$after['tables']['maintenance'][0];$r=$after['tables']['resources'][0];cAssert($job['status']==='Completed'&&$job['completed_at']!==null&&$job['restored_at']!==null,'Corrective completion not settled');cAssert((int)$r['available_stock']===$fixture['stock']&&(int)$r['under_repair_stock']===0,'Corrective repair restored twice/incorrectly');$count=count(array_filter($after['tables']['activity'],fn($r)=>$r['action']==='Maintenance Completed'))-count(array_filter($before['tables']['activity'],fn($r)=>$r['action']==='Maintenance Completed'));cAssert($count===1,'Duplicate completion history');return ['maintenance'=>'Completed','available'=>$fixture['stock'],'under_repair'=>0,'completion_events'=>1,'Head_confirmation'=>'verified'];};
        }else{
            $plan=vPlan($label,$i%2===0?'Serialized':'Aggregate');$ids=[];$c2Resources=[$plan['resource']];
            if($group==='preventive_generate'){$p=['action'=>'generate','plan_id'=>$plan['plan']];$calls=[['gso_a','admin/preventive_plans.php',$p],['gso_head_b','admin/preventive_plans.php',$p]];$verify=function($before,$after){$jobs=$after['tables']['maintenance'];cAssert(count($jobs)===1&&$jobs[0]['status']==='Scheduled'&&$jobs[0]['started_at']===null,'Duplicate active preventive occurrence or implicit activation');cAssert($before['tables']['resources']===$after['tables']['resources'],'Scheduling moved current inventory');return ['occurrences'=>1,'status'=>'Scheduled','current_inventory'=>'unchanged'];};
            }else{$job=vGenerate($plan);$start=['action'=>'start_schedule','maintenance_id'=>$job];$calls=[['gso_a','admin/maintenance.php',$start],[$group==='maintenance_conflict'?'gso_head_b':'gso_b','admin/maintenance.php',$group==='maintenance_conflict'?['action'=>'cancel_schedule','maintenance_id'=>$job]:$start]];
                $verify=function($before,$after)use($group,$plan){$w=$after['tables']['maintenance'][0];$r=$after['tables']['resources'][0];$started=count(array_filter($after['tables']['activity'],fn($r)=>$r['action']==='Preventive Maintenance Start'))-count(array_filter($before['tables']['activity'],fn($r)=>$r['action']==='Preventive Maintenance Start'));cAssert($started<=1,'Duplicate preventive start audit');
                    if($group==='maintenance_start'){cAssert($w['status']==='In Progress'&&$w['started_at']!==null&&$started===1&&(int)$r['available_stock']===$plan['stock']-$plan['hold']&&(int)$r['under_repair_stock']===$plan['hold'],'Preventive start applied incorrectly');return ['status'=>'In Progress','start_events'=>1,'available'=>(int)$r['available_stock'],'under_repair'=>(int)$r['under_repair_stock']];}
                    cAssert($w['status']==='Cancelled'&&$w['completed_at']===null&&(int)$r['available_stock']===$plan['stock']&&(int)$r['under_repair_stock']===0,'Conflicting start/cancel final state impossible');return ['status'=>'Cancelled','start_won_first'=>$started===1,'available'=>$plan['stock'],'under_repair'=>0,'note'=>'Start may serialize before a legitimate cancellation; both ordered transitions are allowed.'];};}
        }
        cRace($label,$ids,$calls,$verify);
    }
    cSave('c2a_completion.json',['complete'=>true,'races'=>count($results),'passed'=>count(array_filter($results,fn($r)=>$r['passed']))]);echo 'C2A COMPLETE: '.count($results).' pairs passed.'.PHP_EOL;
}catch(Throwable $e){cSave('c2a_failure_'.date('Ymd_His').'.private.json',['message'=>$e->getMessage(),'last_label'=>$label??'setup','results'=>$results]);fwrite(STDERR,'STOP C2A: '.$e->getMessage().PHP_EOL);exit(1);}
